const language=()=>{const l=(document.documentElement.lang||'de').slice(0,2).toLowerCase();return copy[l]?l:'de'};
let currentLanguage=null,active=-1,scheduled=false;
function sceneText(){label.textContent=copy[currentLanguage||language()].active[Math.max(0,active)];}
function translate(){const next=language();if(currentLanguage===next)return;currentLanguage=next;const dict=copy[next];for(const el of section.querySelectorAll('[data-story-text]')){const key=el.dataset.storyText,val=dict[key];if(!val)continue;if(key==='title')el.innerHTML=val;else if(el.tagName==='A'){const arrow=el.querySelector('[aria-hidden="true"]');el.textContent=val+' ';if(arrow)el.appendChild(arrow);}else el.textContent=val;}section.setAttribute('aria-label',next==='de'?'Interaktive Tour durch Fahrzeugsysteme':next==='en'?'Interactive vehicle-system tour':'Etkileşimli araç sistemi turu');sceneText();}
function update(){scheduled=false;if(!section.isConnected)return;translate();const vh=window.innerHeight||800;const trigger=vh*(window.matchMedia('(max-width:850px)').matches?.66:.56);let next=0;chapters.forEach((node,i)=>{if(node.getBoundingClientRect().top<=trigger)next=i});const rect=section.getBoundingClientRect();const distance=Math.max(1,rect.height-vh);const progress=Math.max(0,Math.min(1,(trigger-rect.top)/distance));stage.style.setProperty('--story-progress',progress.toFixed(4));if(active!==next){active=next;stage.dataset.active=String(next);counter.textContent=String(next+1).padStart(2,'0')+' / 04';chapters.forEach((node,i)=>node.classList.toggle('is-active',i===next));sceneText();}}
function schedule(){if(!scheduled){scheduled=true;requestAnimationFrame(update);}}
window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule,{passive:true});new MutationObserver(schedule).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});translate();schedule();
